from src.climbbiomech.pose.landmark_enumeration import PoseLandmarks
from src.sidetracked_days.enum import niche_baby
from src.sidetracked_days.enum import six_seven


def generate_rels(landmarks, option: int = 0):
    if not landmarks.pose_landmarks:
        return

    pose = landmarks.pose_landmarks[0]

    dists = []
    
    if option == 0:
        for i in range(len(niche_baby.keys())-1):
            for x in range(i+1, len(niche_baby.keys())):

                joint1 = pose[PoseLandmarks[niche_baby[i]]]
                joint2 = pose[PoseLandmarks[niche_baby[x]]]

                dists.append([(joint1.x - joint2.x), (joint1.y - joint2.y)])

    elif option == 1:
        for i in range(len(six_seven.keys())-1):
            for x in range(i+1, len(six_seven.keys())):

                joint1 = pose[PoseLandmarks[six_seven[i]]]
                joint2 = pose[PoseLandmarks[six_seven[x]]]

                dists.append([(joint1.x - joint2.x), (joint1.y - joint2.y)])

    return dists

